/* ---------- 睡眠 Zzz 粒子 ---------- */
const zzz=[]; let zNext=0;
function updateZzz(dt){
  if(mode==='sleep' && cur.lidTop>.92){
    zNext-=dt;
    if(zNext<=0){
      zNext=.9+Math.random()*1.4;
      const R=Math.min(W*.16,H*.30);
      // 随机从左/右眼上方冒出
      const eye=Math.random()<.5?-1:1;
      zzz.push({
        x:W/2+eye*R*1.35*(Math.random()*.5+.9), y:H*.46-R*.7,
        vy:-(R*.28+Math.random()*R*.2), sway:R*(.15+Math.random()*.2),
        ph:Math.random()*7, size:R*(.16+Math.random()*.16),
        life:0, ttl:2.6+Math.random()*1.2, rot:(Math.random()-.5)*.5
      });
    }
  }
  for(let i=zzz.length-1;i>=0;i--){
    const z=zzz[i]; z.life+=dt;
    if(z.life>z.ttl){zzz.splice(i,1);continue;}
    z.y+=z.vy*dt;
  }
}
function drawZzz(){
  for(const z of zzz){
    const p=z.life/z.ttl;
    const a=p<.15? p/.15 : (1-p)/.85;      // 淡入淡出
    ctx.save();
    ctx.translate(z.x+Math.sin(z.life*2+z.ph)*z.sway, z.y);
    ctx.rotate(z.rot+Math.sin(z.life*1.5+z.ph)*.15);
    ctx.globalAlpha=a*.85;
    ctx.fillStyle='rgba(165,195,255,1)';
    ctx.font=`bold ${z.size*(1+p*.6)|0}px Georgia`;
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText('Z',0,0);
    ctx.restore();
  }
  ctx.globalAlpha=1;
}

