const zzz=[]; let zNext=0;
function updateZzz(dt){
  const R=Math.min(W*.16,H*.30), CR=R*1.55;
  if(mode==='sleep' && cur.lidTop>.92){
    zNext-=dt;
    if(zNext<=0){
      zNext=.8+Math.random()*1.2;
      zzz.push({
        side:Math.random()<.5?-1:1,
        ox:(Math.random()*2-1)*CR*.55,       // 圆屏内横向随机
        y:CR*1.1,                            // 相对屏心：从屏底下方进入
        vy:-(CR*.30+Math.random()*CR*.15),
        sway:CR*(.08+Math.random()*.10),
        ph:Math.random()*7, size:R*(.15+Math.random()*.15),
        life:0, rot:(Math.random()-.5)*.5
      });
    }
  }
  for(let i=zzz.length-1;i>=0;i--){
    const z=zzz[i]; z.life+=dt; z.y+=z.vy*dt;
    if(z.y<-CR*1.2) zzz.splice(i,1);         // 飘出屏顶回收
  }
}
function drawZzz(side,ex,cy,CR){
  for(const z of zzz){
    if(z.side!==side)continue;
    const p=clamp((CR*1.1-z.y)/(CR*2.2),0,1);        // 底→顶进度
    const a=Math.sin(p*Math.PI);                     // 入淡入、出淡出
    ctx.save();
    ctx.translate(ex+z.ox+Math.sin(z.life*2+z.ph)*z.sway, cy+z.y);
    ctx.rotate(z.rot+Math.sin(z.life*1.5+z.ph)*.15);
    ctx.globalAlpha=a*.85;
    ctx.fillStyle='rgba(165,195,255,1)';
    ctx.font=`bold ${z.size*(1+p*.5)|0}px Georgia`;
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText('Z',0,0);
    ctx.restore();
  }
  ctx.globalAlpha=1;
}
